import React, { useState, useMemo } from "react";


export default function NewsStack({
    items = [],
    width = 520,
    height = 260,
    className = "",
    title = "Actualités",
}) {
    const [hovered, setHovered] = useState(null);

    // Offsets et rotations (pile à 3 niveaux)
    const layers = useMemo(
        () => [
            { top: 0, left: 0, rotate: 0, z: 10 }, // back
            { top: 28, left: 36, rotate: -2, z: 20 }, // middle
            { top: 56, left: 72, rotate: 0.8, z: 30 }, // front
        ],
        []
    );

    const styleOnHover = (i) => {
        const isHover = hovered === i;
        return {
            transform: `rotate(${layers[i].rotate}deg) scale(${isHover ? 1.04 : 1})`,
            zIndex: isHover ? 50 : layers[i].z,
            boxShadow: isHover
                ? "0 18px 44px rgba(0,0,0,.38)"
                : "0 12px 28px rgba(0,0,0,.22)",
            filter: isHover ? "saturate(1.06) contrast(1.02)" : "saturate(.92)",
            transition: "transform .24s ease, box-shadow .24s ease, filter .24s ease",
        };
    };

    return (
        <div className={`relative ${className}`}>
            {/* {title && (
                <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">{title}</h3>
            )} */}

            {/* Conteneur pile */}
            <div
                className="relative"
                style={{
                    width: "100%",
                    maxWidth: width,
                    height: height + 120, // marge pour la pile
                }}
            >

                {items.slice(0, 3).map((it, i) => (
                    <article
                        key={i}
                        className="absolute rounded-xl overflow-hidden bg-white cursor-pointer"
                        style={{
                            top: layers[i].top + (i === 0 ? 20 : 0),
                            left: layers[i].left + (i === 0 ? 20 : 0),
                            width: "100%",
                            maxWidth: width,
                            height,
                            ...styleOnHover(i),
                        }}
                        onMouseEnter={() => setHovered(i)}
                        onMouseLeave={() => setHovered(null)}
                    >
                        <a
                            href={it.href || "#"}
                            className="block w-full h-full relative"
                            aria-label={it.title}
                        >
                            {/* Image */}
                            <img
                                src={it.img}
                                alt={it.title}
                                className="absolute inset-0 w-full h-full object-cover"
                                loading="lazy"
                            />

                            {/* Liseré bleu à droite (détail maquette) */}
                            <div className="absolute top-3 right-3 h-[88%] w-1 rounded bg-[#5aa4ff]" />

                            {/* Voile + Texte : toujours visible sur la carte avant ; au survol sinon */}
                            <div
                                className={`absolute inset-0 flex items-end p-5 text-white
                  ${hovered === i || i === 2 ? "" : "opacity-0"} 
                `}
                                style={{
                                    background:
                                        "linear-gradient(to top, rgba(0,0,0,.70) 0%, rgba(0,0,0,.05) 60%, rgba(0,0,0,0) 100%)",
                                    transition: "opacity .2s ease",
                                }}
                            >
                                <div className="w-full">
                                    <h4
                                        className="text-lg font-semibold leading-tight"
                                        style={{
                                            display: "-webkit-box",
                                            WebkitLineClamp: 2,
                                            WebkitBoxOrient: "vertical",
                                            overflow: "hidden",
                                        }}
                                    >
                                        {it.title}
                                    </h4>
                                    <p
                                        className="text-sm opacity-95 mt-1"
                                        style={{
                                            display: "-webkit-box",
                                            WebkitLineClamp: 2,
                                            WebkitBoxOrient: "vertical",
                                            overflow: "hidden",
                                        }}
                                    >
                                        {it.excerpt}
                                    </p>
                                </div>
                            </div>
                        </a>
                    </article>
                ))}
            </div>
        </div>
    );
}
